import os
import time

import pandas as pd

import kaggle_benchmarks as kbench

# ---------------------------------------------------------------- config
LEVELS = ["none"]
R = 3
CACHE_PROBE = False
N_JOBS = 8
SEED_BASE = 1000  # seed = SEED_BASE + repeat (google/* models drop the seed)
KNOWN_NAMES = ["Ana", "Ben", "Cleo", "Dev", "Eli", "Fay", "Gus", "Hana"]

# ---------------------------------------------------------------- parser
# Inlined verbatim from src/dial/parse.py
"""Answer parser (Tech Design §4). Pure stdlib; inlined into each Kaggle task file.

Outcomes: "correct", "wrong", "format_fail" (strict extraction unparseable).
"api_error" is assigned by the caller when the model call itself raised.
"""

import re

_THINK_BLOCK = re.compile(r"<think>.*?</think>", re.IGNORECASE | re.DOTALL)
_THINK_OPEN = re.compile(r"<think>", re.IGNORECASE)
_THINK_CLOSE = re.compile(r"</think>", re.IGNORECASE)
_MARKER = re.compile(
    r"FINAL[ \t]+ANSWER[ \t]*[*_`]*[ \t]*[:：][ \t]*(.*)$",
    re.IGNORECASE | re.MULTILINE,
)
_THOUSANDS = re.compile(r"(?<=\d),(?=\d{3}(?!\d))")
_INT = re.compile(r"-?\d+")


def strip_think(raw: str) -> str:
    """Remove <think> blocks. An unclosed <think> runs to the end of the text;
    a stray </think> with no opener removes everything before it."""
    text = _THINK_BLOCK.sub("", raw)
    m = _THINK_OPEN.search(text)
    if m:
        text = text[: m.start()]
    closes = list(_THINK_CLOSE.finditer(text))
    if closes:
        text = text[closes[-1].end():]
    return text


def _clean(s: str) -> str:
    s = s.strip()
    s = re.sub(r"[*_`]", "", s)
    s = s.strip().strip("\"'“”‘’").strip()
    s = s.rstrip(".,!").strip()
    return s


def normalize(s: str, answer_type: str, known_names: list[str]):
    """Return the normalized answer (int or canonical name), or None if unparseable."""
    if s is None:
        return None
    s = _clean(s)
    if answer_type == "int":
        m = _INT.search(_THOUSANDS.sub("", s))
        return int(m.group()) if m else None
    if answer_type == "name":
        found = {
            n for n in known_names
            if re.search(rf"(?<![A-Za-z]){re.escape(n)}(?![A-Za-z])", s, re.IGNORECASE)
        }
        return found.pop() if len(found) == 1 else None
    raise ValueError(f"unknown answer_type {answer_type!r}")


def parse(raw: str, answer_type: str, known_names: list[str]) -> dict:
    """Strict extraction from the last FINAL ANSWER line; lenient fallback on the
    last non-empty visible line (secondary accuracy only)."""
    visible = strip_think(raw or "")
    markers = list(_MARKER.finditer(visible))
    parsed = normalize(markers[-1].group(1), answer_type, known_names) if markers else None
    lenient = parsed
    if lenient is None:
        lines = [ln for ln in visible.splitlines() if ln.strip()]
        if lines:
            lenient = normalize(lines[-1], answer_type, known_names)
    return {
        "parsed": parsed,
        "lenient_parsed": lenient,
        "outcome_hint": "ok" if parsed is not None else "format_fail",
    }


def grade(parsed, expected, answer_type: str) -> bool:
    if parsed is None:
        return False
    if answer_type == "int":
        return parsed == int(expected)
    return str(parsed).lower() == str(expected).lower()


def outcome(parsed, expected, answer_type: str) -> str:
    if parsed is None:
        return "format_fail"
    return "correct" if grade(parsed, expected, answer_type) else "wrong"

# ---------------------------------------------------------------- items
ITEMS = []  # PLACEHOLDER: test items are inlined at M4 from data/test_items.json


def _caching_state():
    try:
        from kaggle_benchmarks._config import config

        return str(getattr(config, "enable_caching", "unknown"))
    except Exception as e:  # newer library builds may move the config
        return f"unknown ({type(e).__name__})"


CACHING = _caching_state()


def _select_items():
    if os.environ.get("DIAL_SMOKE") == "1":
        seen, picked = set(), []
        for it in ITEMS:
            if it["family"] not in seen:
                seen.add(it["family"])
                picked.append(it)
        return picked
    return ITEMS


@kbench.task(name="dial-call-none", store_task=False, store_run=False)
def dial_call(llm, item_id: str, family: str, answer_type: str, prompt: str,
              answer: str, level: str, repeat: int, probe: int) -> dict:
    """One model call: prompt, parse, grade, and record usage."""
    repeat, probe = int(repeat), int(probe)
    rec = {
        "item_id": item_id, "family": family, "level": level, "repeat": repeat,
        "probe": probe, "expected": str(answer), "caching": CACHING,
        "raw": None, "parsed": None, "lenient_parsed": None, "outcome": None,
        "output_tokens": None, "input_tokens": None, "cost_nanodollars": None,
        "trace_chars": None, "latency_s": None, "backend_latency_ms": None,
        "error": None,
    }
    name = f"{item_id}|{level}|r{repeat}" + (f"|probe{probe}" if probe else "")
    t0 = time.perf_counter()
    with kbench.chats.new(name) as chat:
        try:
            raw = llm.prompt(prompt, reasoning=level, seed=SEED_BASE + repeat)
            traces = kbench.last_reasoning_traces()
        except Exception as e:
            raw, traces = None, None
            rec["error"] = f"{type(e).__name__}: {e}"
        u = chat.usage
    rec["latency_s"] = round(time.perf_counter() - t0, 3)
    rec["output_tokens"] = u.output_tokens
    rec["input_tokens"] = u.input_tokens
    rec["cost_nanodollars"] = u.total_cost_nanodollars
    rec["backend_latency_ms"] = u.total_backend_latency_ms
    if raw is None:
        rec["outcome"] = "api_error"
        return rec
    rec["raw"] = str(raw)
    rec["trace_chars"] = len(traces) if traces else 0
    p = parse(rec["raw"], answer_type, KNOWN_NAMES)
    parsed = p["parsed"]
    rec["parsed"] = None if parsed is None else str(parsed)
    rec["lenient_parsed"] = None if p["lenient_parsed"] is None else str(p["lenient_parsed"])
    rec["outcome"] = outcome(parsed, answer, answer_type)
    return rec


def _rows(items, levels, repeats, probe=0):
    return [
        {"item_id": it["id"], "family": it["family"], "answer_type": it["answer_type"],
         "prompt": it["prompt"], "answer": it["answer"], "level": lv,
         "repeat": r, "probe": probe}
        for lv in levels for r in range(repeats) for it in items
    ]


def _records(runs):
    out = []
    for run in runs:
        if isinstance(run.result, dict):
            out.append(run.result)
        else:
            out.append({"outcome": "task_error", "error": str(getattr(run, "error_message", ""))})
    return out


@kbench.task(name="dial-none", description="Reasoning Dial: accuracy, output tokens and cost at one reasoning-effort level (see task name) on three seeded task families: Deduce, Arith, Distract.")
def dial_task(llm) -> float:
    items = _select_items()
    if not items:
        raise RuntimeError("No items inlined in this task file yet (test items are inlined at M4).")
    df = pd.DataFrame(_rows(items, LEVELS, R))
    records = _records(dial_call.evaluate(
        llm=[llm], evaluation_data=df, n_jobs=N_JOBS, on_failure="continue"))
    if CACHE_PROBE:
        # Two items, each sent twice at "none" with identical requests, sequentially,
        # so a cached first reply would be returned for the second.
        probe_items = items[:2]
        probe_df = pd.DataFrame(_rows(probe_items, ["none"], 1, probe=1)
                                + _rows(probe_items, ["none"], 1, probe=2))
        probe_records = _records(dial_call.evaluate(
            llm=[llm], evaluation_data=probe_df, n_jobs=1, on_failure="continue"))
        for it in probe_items:
            texts = [r.get("raw") for r in probe_records if r.get("item_id") == it["id"]]
            print(f"[cache-probe] {it['id']}: byte_identical={len(set(texts)) == 1} "
                  f"caching={CACHING}")
        records += probe_records
    graded = [r for r in records if r.get("probe") == 0 and r["outcome"] in ("correct", "wrong", "format_fail")]
    acc = sum(r["outcome"] == "correct" for r in graded) / len(graded) if graded else 0.0
    counts = {}
    for r in records:
        counts[r["outcome"]] = counts.get(r["outcome"], 0) + 1
    print(f"[dial] levels={LEVELS} R={R} items={len(items)} calls={len(records)} "
          f"outcomes={counts} primary_accuracy={acc:.3f} caching={CACHING}")
    return float(acc)


dial_task.run(kbench.llm)
